import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
def mk(shape):
    def model(p):
        a,b,c0,d0,d1,e0,e1=p[:7]
        q=p[7:]
        if shape=='sin': g=q[0]*np.sin(q[1]*t+q[2])
        elif shape=='texp': g=q[0]*t*np.exp(-q[1]*t)
        elif shape=='pow': g=q[0]*t**q[1]*np.exp(-q[2]*t)
        elif shape=='sintexp': g=q[0]*np.sin(q[1]*t+q[2])*np.exp(-q[3]*t)
        return a*P+b*P**2+(c0+e1*t+g)/P+d0+d1*t
    return model
def fit(shape,nq,trials=60):
    best=None
    rng=np.random.default_rng(0)
    for _ in range(trials):
        p0=np.concatenate([rng.normal(0,1,7), rng.uniform(0.1,2,nq)])
        if shape=='sin': p0[8]=rng.uniform(0.2,0.6)
        if shape=='sintexp': p0[8]=rng.uniform(0.2,0.6)
        try:
            r=least_squares(lambda p: mk(shape)(p)-y, p0)
        except Exception: continue
        if best is None or r.cost<best.cost: best=r
    return best
for shape,nq in [('sin',3),('texp',2),('pow',3),('sintexp',4)]:
    r=fit(shape,nq)
    print(shape, np.mean((mk(shape)(r.x)-y)**2)/np.var(y), np.round(r.x,4))

